CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY, code text UNIQUE NOT NULL CHECK(code ~ '^[0-9]{1,12}$'), name text NOT NULL, pin_hash text NOT NULL, role text NOT NULL CHECK(role IN ('employee','supervisor','admin')), department text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE machines(id uuid PRIMARY KEY, code text UNIQUE NOT NULL, name text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE stations(id uuid PRIMARY KEY, code text UNIQUE NOT NULL, name text NOT NULL, machine_id uuid NOT NULL REFERENCES machines(id), sector text NOT NULL, line text NOT NULL, target numeric NOT NULL CHECK(target>0), status text NOT NULL DEFAULT 'available' CHECK(status IN ('available','stopped','maintenance','problem')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE devices(id uuid PRIMARY KEY, station_id uuid NOT NULL REFERENCES stations(id), token_hash text UNIQUE NOT NULL, label text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE orders(id uuid PRIMARY KEY, code text UNIQUE NOT NULL, product text NOT NULL, reference text NOT NULL, quantity integer NOT NULL CHECK(quantity>0), target numeric CHECK(target>0), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','production','paused','finished','cancelled')), start_date date, due_date date, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE pause_types(id uuid PRIMARY KEY, name text UNIQUE NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE work_sessions(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), station_id uuid NOT NULL REFERENCES stations(id), machine_id uuid NOT NULL REFERENCES machines(id), order_id uuid NOT NULL REFERENCES orders(id), shift text NOT NULL, status text NOT NULL CHECK(status IN ('production','pause','finished')), started_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz, checkpoint_at timestamptz NOT NULL DEFAULT now(), productive_ms double precision NOT NULL DEFAULT 0 CHECK(productive_ms>=0), pause_ms double precision NOT NULL DEFAULT 0 CHECK(pause_ms>=0), expected double precision NOT NULL DEFAULT 0 CHECK(expected>=0), target numeric NOT NULL CHECK(target>0), quantity integer NOT NULL DEFAULT 0 CHECK(quantity>=0), version integer NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_active_user ON work_sessions(user_id) WHERE status <> 'finished';
CREATE UNIQUE INDEX one_active_station ON work_sessions(station_id) WHERE status <> 'finished';
CREATE INDEX sessions_dates ON work_sessions(started_at);
CREATE INDEX sessions_order ON work_sessions(order_id);
CREATE INDEX sessions_machine ON work_sessions(machine_id);
CREATE TABLE pauses(id uuid PRIMARY KEY, session_id uuid NOT NULL REFERENCES work_sessions(id), type_id uuid NOT NULL REFERENCES pause_types(id), reason text NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz);
CREATE UNIQUE INDEX one_open_pause ON pauses(session_id) WHERE ended_at IS NULL;
CREATE TABLE production_records(id uuid PRIMARY KEY, session_id uuid NOT NULL REFERENCES work_sessions(id), user_id uuid NOT NULL REFERENCES users(id), previous integer NOT NULL, quantity integer NOT NULL, delta integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX records_session ON production_records(session_id,created_at);
CREATE TABLE target_changes(id uuid PRIMARY KEY, session_id uuid REFERENCES work_sessions(id), station_id uuid REFERENCES stations(id), order_id uuid REFERENCES orders(id), user_id uuid NOT NULL REFERENCES users(id), previous numeric, target numeric NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE auth_sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE login_limits(key text PRIMARY KEY, attempts integer NOT NULL, reset_at timestamptz NOT NULL);
CREATE TABLE requests(user_id uuid NOT NULL REFERENCES users(id), key uuid NOT NULL, fingerprint text NOT NULL, result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,key));
CREATE TABLE audit_logs(id uuid PRIMARY KEY, user_id uuid REFERENCES users(id), action text NOT NULL, entity_id text, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_dates ON audit_logs(created_at);
CREATE TABLE settings(id integer PRIMARY KEY CHECK(id=1), company text NOT NULL DEFAULT 'Fábrica Flow', warning_threshold integer NOT NULL DEFAULT 90 CHECK(warning_threshold BETWEEN 1 AND 99), timezone text NOT NULL DEFAULT 'Europe/Lisbon');
